COB.FLDID9, COB.FLDTAG9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9,  GENHTAB_9.FLDSEARCH AS FLDSEARCH9, GENHTAB_9.FLDCRITERIA AS FLDCRITERIA9, GENHTAB_9.FLDENCRYPTF as FLDENCRYPTF9, GENHTAB_9.FLDLOWER as FLDLOWER9, GENHTAB_9.FLDUPPER as FLDUPPER9, GENHTAB_9.FLDREGEX as FLDREGEX9, CASE WHEN GENHTAB_9.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF9, GENHTAB_9.FLDCHGINF AS FLDCHGINF9,
