COB.FLDID12, COB.FLDTAG12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  GENHTAB_12.FLDSEARCH AS FLDSEARCH12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12, GENHTAB_12.FLDENCRYPTF as FLDENCRYPTF12, GENHTAB_12.FLDLOWER as FLDLOWER12, GENHTAB_12.FLDUPPER as FLDUPPER12, GENHTAB_12.FLDREGEX as FLDREGEX12, CASE WHEN GENHTAB_12.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF12, GENHTAB_12.FLDCHGINF AS FLDCHGINF12,
