TOI_EXT.FLDID12, TOI_EXT.FLDTAG12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  GENHTAB_12.FLDSEARCH AS FLDSEARCH12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12, GENHTAB_12.FLDENCRYPTF as FLDENCRYPTF12, GENHTAB_12.FLDLOWER as FLDLOWER12, GENHTAB_12.FLDUPPER as FLDUPPER12, GENHTAB_12.FLDREGEX as FLDREGEX12, CASE WHEN GENHTAB_12.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF12, GENHTAB_12.FLDVALUATION AS FLDVALUATION12,
TOI_EXT.FLDID13, TOI_EXT.FLDTAG13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDENCRYPTF as FLDENCRYPTF13, GENHTAB_13.FLDLOWER as FLDLOWER13, GENHTAB_13.FLDUPPER as FLDUPPER13, GENHTAB_13.FLDREGEX as FLDREGEX13, CASE WHEN GENHTAB_13.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF13, GENHTAB_13.FLDVALUATION AS FLDVALUATION13,
TOI_EXT.FLDID14, TOI_EXT.FLDTAG14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDENCRYPTF as FLDENCRYPTF14, GENHTAB_14.FLDLOWER as FLDLOWER14, GENHTAB_14.FLDUPPER as FLDUPPER14, GENHTAB_14.FLDREGEX as FLDREGEX14, CASE WHEN GENHTAB_14.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF14, GENHTAB_14.FLDVALUATION AS FLDVALUATION14,
TOI_EXT.FLDID15, TOI_EXT.FLDTAG15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15, GENHTAB_15.FLDENCRYPTF as FLDENCRYPTF15, GENHTAB_15.FLDLOWER as FLDLOWER15, GENHTAB_15.FLDUPPER as FLDUPPER15, GENHTAB_15.FLDREGEX as FLDREGEX15, CASE WHEN GENHTAB_15.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF15, GENHTAB_15.FLDVALUATION AS FLDVALUATION15
FROM               
 TOI
 LEFT JOIN TOI_EXT on (TOI_EXT.TOI=TOI.TOI AND TOI_EXT.NOC = @P_NOC)
 LEFT OUTER JOIN GENHTAB as GENHTAB_1 ON TOI_EXT.FLDID1 = GENHTAB_1.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_2 ON TOI_EXT.FLDID2 = GENHTAB_2.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_3 ON TOI_EXT.FLDID3 = GENHTAB_3.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_4 ON TOI_EXT.FLDID4 = GENHTAB_4.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_5 ON TOI_EXT.FLDID5 = GENHTAB_5.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_6 ON TOI_EXT.FLDID6 = GENHTAB_6.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON TOI_EXT.FLDID7 = GENHTAB_7.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON TOI_EXT.FLDID8 = GENHTAB_8.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON TOI_EXT.FLDID9 = GENHTAB_9.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON TOI_EXT.FLDID10 = GENHTAB_10.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON TOI_EXT.FLDID11 = GENHTAB_11.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON TOI_EXT.FLDID12 = GENHTAB_12.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_13 ON TOI_EXT.FLDID13 = GENHTAB_13.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON TOI_EXT.FLDID14 = GENHTAB_14.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_15 ON TOI_EXT.FLDID15 = GENHTAB_15.FLDID      
WHERE TOI.TOI = @P_TOI
 

